const project=()=>state.projects.find(p=>p.id===state.activeProjectId)||state.projects[0];
const member=id=>state.members.find(m=>m.id===id);
const myId=()=>auth.hosted?auth.member?.id:(state.members.find(m=>m.id==='me')?.id??state.members.find(m=>m.name===state.profile.name)?.id);
const viewer=()=>auth.hosted?{name:auth.member?.name||'',initials:auth.member?.name?.slice(0,2)||''}:state.profile;
const canInvite=()=>!auth.hosted||auth.member?.role==='admin';
const today=()=>new Date().toLocaleDateString('sv-SE');
const dateLabel=d=>d?new Date(d+'T00:00:00').toLocaleDateString('ko-KR',{month:'long',day:'numeric'}):'—';
const dateRange=t=>{if(!t.startDate||!t.dueDate||t.startDate===t.dueDate)return t.dueDate===today()?'오늘':dateLabel(t.dueDate);const first=t.startDate===today()?'오늘':dateLabel(t.startDate),last=t.startDate!==today()&&t.startDate.slice(0,7)===t.dueDate.slice(0,7)?`${Number(t.dueDate.slice(8))}일`:dateLabel(t.dueDate);return `${first} – ${last}`};
const taskList=()=>filterTasks(state,{projectId:ui.page==='my'?'':project().id,query:ui.query,status:ui.status,assignee:ui.assignee==='unassigned'?'':ui.assignee,priority:ui.priority,sort:ui.sort,onlyMine:false}).filter(t=>ui.page!=='my'||t.assignee===myId());
function toast(message, action){ const el=document.createElement('div');el.className='toast';el.append(document.createTextNode(message));if(action){const b=document.createElement('button');b.textContent=action.label;b.onclick=()=>{action.run();el.remove()};el.append(b)}$('#toast-stack').append(el);setTimeout(()=>el.remove(),5000); }
const apiRequest=(route,method='GET',body,signal)=>auth.request(route,method,body,signal);
function cacheState(){if(auth.hosted)return;try{saveState(state)}catch(error){toast('브라우저 백업 저장 실패: '+error.message)}}
function adoptWorkspace(value){const selected=apiConnected?state.activeProjectId:null;state=validateImport(value);if(auth.hosted&&state.projects.some(p=>p.id===selected))state.activeProjectId=selected;}
async function connectStore(){const generation=auth.generation;try{let saved=await apiRequest('/api/workspace');if(!saved.initialized){if(auth.hosted)throw new Error('공유 업무 공간을 아직 준비하고 있습니다. 관리자에게 확인해 주세요.');saved=await apiRequest('/api/bootstrap','POST',{workspace:state});}if(auth.hosted&&generation!==auth.generation)return;adoptWorkspace(saved.workspace);serverRevision=saved.revision;apiConnected=true;cacheState();$('#app').className='app-shell';render()}catch(error){if(auth.hosted&&generation!==auth.generation)return;apiConnected=false;if(auth.hosted)auth.showConnectionError(error.message,()=>{serverInit=connectStore()});else render()}}
function isEditingWorkspace(){return drawerTask||$('dialog')||meetingController?.isEditing||/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName)}
async function refreshStore(force=false){if(!apiConnected||mutating||(!force&&isEditingWorkspace()))return;const requestedRevision=serverRevision,generation=auth.generation;try{const saved=await apiRequest('/api/workspace');if((auth.hosted&&generation!==auth.generation)||mutating||(!force&&isEditingWorkspace())||serverRevision!==requestedRevision)return;if(saved.revision>serverRevision){adoptWorkspace(saved.workspace);serverRevision=saved.revision;cacheState();render()}}catch{}}
async function persist(){const clean=validateImport(state);if(apiConnected){const saved=await apiRequest('/api/workspace','PUT',{revision:serverRevision,workspace:clean});adoptWorkspace(saved.workspace);serverRevision=saved.revision;cacheState()}else{if(auth.hosted)throw new Error('서버에 연결된 후 저장할 수 있습니다.');state=saveState(clean)}return true}
async function change(fn,message){await serverInit;if(auth.hosted&&(!auth.member||!apiConnected)){toast('로그인과 서버 연결을 확인해 주세요.');return false}if(mutating){toast('저장 중입니다. 잠시 후 다시 시도해 주세요.');return false}mutating=true;const previous=structuredClone(state),generation=auth.generation;try{fn();await persist();if(auth.hosted&&generation!==auth.generation)return false;render();if(message)toast(message);return true}catch(error){if(auth.hosted&&generation!==auth.generation)return false;state=previous;if(error.code===409){try{const latest=await apiRequest('/api/workspace');if(auth.hosted&&generation!==auth.generation)return false;adoptWorkspace(latest.workspace);serverRevision=latest.revision;cacheState()}catch{}toast('새로 등록된 업무를 반영했습니다. 변경 내용을 확인하고 다시 저장해 주세요.')}else toast('저장하지 못했습니다: '+error.message);render();return false}finally{mutating=false}}

function avatar(m,size=''){return m?`<span class="avatar ${size}" style="background:${esc(m.color)}" title="${esc(m.name)}">${esc(m.initials)}</span>`:`<span class="avatar unassigned ${size}" title="담당자 없음">${icon('user')}</span>`}
const pill=t=>healthLabel[t.health]?`<span class="pill health-${t.health}" title="${healthLabel[t.health]}">${healthLabel[t.health]}</span>`:'';
const priority=t=>`<span class="pill priority-${t.priority}">${priorityLabel[t.priority]}</span>`;
function navItem(page,label,ic){return `<button class="nav-item ${ui.page===page?'active':''}" data-action="page" data-page="${page}">${icon(ic)}<span>${label}</span>${page==='my'?`<span class="nav-count">${state.tasks.filter(t=>t.assignee===myId()&&t.status!=='done').length}</span>`:''}</button>`}
function saveViewPreferences(){try{localStorage.setItem('flowdesk.view-preferences.v1',JSON.stringify(viewPreferences));}catch{toast('보기 설정을 이 브라우저에 저장하지 못했습니다.');}}
function railItem(label,ic,action,attributes='',active=false){return `<button class="rail-item ${active?'active':''}" data-action="${action}" ${attributes} title="${label}" aria-label="${label}">${icon(ic)}<span>${label}</span></button>`}
function viewTabs(){return `<nav class="view-tabs" aria-label="프로젝트 보기">${[['overview','개요'],['list','목록'],['board','보드'],['timeline','타임라인'],['dashboard','대시보드'],['calendar','캘린더']].filter(v=>ui.page!=='my'||['list','board','calendar'].includes(v[0])).map(([key,label])=>`<button data-action="view" data-view="${key}" class="${ui.view===key?'active':''}" aria-current="${ui.view===key?'page':'false'}">${label}</button>`).join('')}<button class="icon-btn add-view" data-action="choose-view" aria-label="기본 보기 선택">${icon('plus')}</button></nav>`}
function viewChoiceBanner(){if(ui.page!=='project'||viewPreferences.dismissed[project().id])return '';return `<section class="view-choice-banner" aria-label="기본 보기 선택"><div class="view-choice-heading"><h3>Flowdesk에서 프로젝트를 시작하세요. 기본 보기를 선택하세요.</h3><button class="icon-btn" data-action="dismiss-view-choice" aria-label="보기 선택 안내 닫기">${icon('close')}</button></div><div class="view-choice-options">${[['list','목록','list'],['board','보드','board'],['calendar','캘린더','calendar'],['timeline','타임라인','timeline']].map(([key,label,ic])=>`<button class="view-choice ${ui.view===key?'selected':''}" data-action="view" data-view="${key}" aria-pressed="${ui.view===key}">${icon(ic)}<span>${label}</span></button>`).join('')}<button class="btn primary view-choice-continue" data-action="continue-view-choice">계속</button></div></section>`}
