 if(auth.hosted&&(!auth.member||!apiConnected))return;
 meetingController?.destroy();meetingController=null;
 const p=project(), tasks=state.tasks.filter(t=>t.projectId===p.id), done=tasks.filter(t=>t.status==='done').length;
 const title=ui.page==='home'?'홈':ui.page==='my'?'내 작업':ui.page==='meetings'?'회의록 자동 등록':p.name;
